    public Object parseLedgerEntry(Map<String, Object> item, Object... optionalArgs)
    {
        //
        // spot
        //
        //     {
        //         "billId": "1111506298997215233",
        //         "coin": "USDT",
        //         "groupType": "transfer",
        //         "businessType": "transfer_out",
        //         "size": "-11.64958799",
        //         "balance": "0.00000000",
        //         "fees": "0.00000000",
        //         "cTime": "1700729673028"
        //     }
        //
        // swap and future
        //
        //     {
        //         "billId": "1111499428100472833",
        //         "symbol": "",
        //         "amount": "-11.64958799",
        //         "fee": "0",
        //         "feeByCoupon": "",
        //         "businessType": "trans_to_exchange",
        //         "coin": "USDT",
        //         "cTime": "1700728034996"
        //     }
        //
        Object currency = optionalArgs != null && optionalArgs.length > 0 ? optionalArgs[0] : null;
        String currencyId = this.safeString(item, "coin");
        String code = this.safeCurrencyCode(currencyId, currency);
        currency = this.safeCurrency(currencyId, currency);
        Long timestamp = this.safeInteger(item, "cTime");
        Double after = this.safeNumber(item, "balance");
        Double fee = this.safeNumber2(item, "fees", "fee");
        String amountRaw = this.safeString2(item, "size", "amount", "");
        Object amount = this.parseNumber(Precise.stringAbs(amountRaw));
        String direction = "in";
        if (((String)amountRaw).indexOf("-") >= 0)
        {
            direction = "out";
        }
        final Object finalDirection = direction;
        return this.safeLedgerEntry(new HashMap<String, Object>() {{
            put( "info", item );
            put( "id", Bitget.this.safeString(item, "billId") );
            put( "timestamp", timestamp );
            put( "datetime", Bitget.this.iso8601(timestamp) );
            put( "direction", finalDirection );
            put( "account", null );
            put( "referenceId", null );
            put( "referenceAccount", null );
            put( "type", Bitget.this.parseLedgerType(Bitget.this.safeString(item, "businessType")) );
            put( "currency", code );
            put( "amount", amount );
            put( "before", null );
            put( "after", after );
            put( "status", null );
            put( "fee", new HashMap<String, Object>() {{
                put( "currency", code );
                put( "cost", fee );
            }} );
        }}, currency);
    }

