            Map<String, Object> response = (this.privateConvertGetV2ConvertCurrencies(parameters)).join();
            //
            //     {
            //         "code": "00000",
            //         "msg": "success",
            //         "requestTime": 1712121755897,
            //         "data": [
            //             {
            //                 "coin": "BTC",
